CREATE DATABASE IF NOT EXISTS techstore_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE techstore_db;
SET time_zone = '+00:00';
CREATE TABLE users(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(30),role ENUM('customer','admin') NOT NULL DEFAULT 'customer',status ENUM('active','locked') NOT NULL DEFAULT 'active',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_users_name(name),INDEX idx_users_role_status(role,status)) ENGINE=InnoDB;
CREATE TABLE addresses(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,recipient_name VARCHAR(120) NOT NULL,phone VARCHAR(30) NOT NULL,address_line VARCHAR(500) NOT NULL,is_default BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_addresses_user(user_id)) ENGINE=InnoDB;
CREATE TABLE categories(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,slug VARCHAR(150) NOT NULL UNIQUE,description TEXT,is_active BOOLEAN NOT NULL DEFAULT TRUE,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE brands(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,slug VARCHAR(150) NOT NULL UNIQUE,logo_url VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE products(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL UNIQUE,description TEXT,category_id BIGINT UNSIGNED,brand_id BIGINT UNSIGNED,price DECIMAL(14,2) NOT NULL,original_price DECIMAL(14,2),stock INT UNSIGNED NOT NULL DEFAULT 0,is_featured BOOLEAN NOT NULL DEFAULT FALSE,sales_count INT UNSIGNED NOT NULL DEFAULT 0,status ENUM('active','draft','archived') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,FOREIGN KEY(brand_id) REFERENCES brands(id) ON DELETE SET NULL,INDEX idx_products_search(name),INDEX idx_products_category(category_id,status),INDEX idx_products_brand(brand_id),INDEX idx_products_price(price),INDEX idx_products_status(status)) ENGINE=InnoDB;
CREATE TABLE product_images(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,product_id BIGINT UNSIGNED NOT NULL,image_url VARCHAR(700) NOT NULL,alt_text VARCHAR(240),sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,INDEX idx_images_product(product_id)) ENGINE=InnoDB;
CREATE TABLE product_specs(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,product_id BIGINT UNSIGNED NOT NULL,spec_name VARCHAR(120) NOT NULL,spec_value VARCHAR(500) NOT NULL,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,INDEX idx_specs_product(product_id)) ENGINE=InnoDB;
CREATE TABLE carts(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE cart_items(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,cart_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_cart_product(cart_id,product_id),FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE coupons(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,code VARCHAR(50) NOT NULL UNIQUE,discount_type ENUM('percent','fixed') NOT NULL,discount_value DECIMAL(12,2) NOT NULL,maximum_discount DECIMAL(12,2),minimum_order DECIMAL(12,2) NOT NULL DEFAULT 0,usage_limit INT UNSIGNED NOT NULL,used_count INT UNSIGNED NOT NULL DEFAULT 0,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_coupon_active(code,status,starts_at,ends_at)) ENGINE=InnoDB;
CREATE TABLE orders(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,status ENUM('pending','confirmed','shipping','delivered','completed','cancelled') NOT NULL DEFAULT 'pending',subtotal DECIMAL(14,2) NOT NULL,discount_amount DECIMAL(14,2) NOT NULL DEFAULT 0,total_amount DECIMAL(14,2) NOT NULL,recipient_name VARCHAR(120) NOT NULL,recipient_phone VARCHAR(30) NOT NULL,shipping_address VARCHAR(700) NOT NULL,note TEXT,payment_method ENUM('COD','SIMULATED') NOT NULL DEFAULT 'COD',cancelled_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_orders_user(user_id,created_at),INDEX idx_orders_status(status,created_at)) ENGINE=InnoDB;
CREATE TABLE order_items(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED,product_name VARCHAR(220) NOT NULL,quantity INT UNSIGNED NOT NULL,unit_price DECIMAL(14,2) NOT NULL,line_total DECIMAL(14,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL,INDEX idx_order_items_order(order_id)) ENGINE=InnoDB;
CREATE TABLE payments(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,order_id BIGINT UNSIGNED NOT NULL,method ENUM('COD','SIMULATED') NOT NULL,amount DECIMAL(14,2) NOT NULL,status ENUM('pending','simulated','paid','failed','cancelled','refunded') NOT NULL DEFAULT 'pending',transaction_ref VARCHAR(190),paid_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,INDEX idx_payments_order(order_id)) ENGINE=InnoDB;
CREATE TABLE reviews(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,product_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,comment TEXT,status ENUM('visible','hidden') NOT NULL DEFAULT 'visible',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_review_purchase(product_id,user_id,order_id),CHECK(rating BETWEEN 1 AND 5),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,INDEX idx_reviews_product_status(product_id,status)) ENGINE=InnoDB;
CREATE TABLE coupon_usages(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,coupon_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL,discount_amount DECIMAL(14,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_coupon_order(coupon_id,order_id),FOREIGN KEY(coupon_id) REFERENCES coupons(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(order_id) REFERENCES orders(id),INDEX idx_coupon_user(coupon_id,user_id)) ENGINE=InnoDB;
CREATE TABLE wishlists(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE wishlist_items(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,wishlist_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_wishlist_product(wishlist_id,product_id),FOREIGN KEY(wishlist_id) REFERENCES wishlists(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE inventory_transactions(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,product_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED,quantity_change INT NOT NULL,type ENUM('sale','return','restock','adjustment') NOT NULL,note VARCHAR(500),created_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_inventory_product(product_id,created_at)) ENGINE=InnoDB;
CREATE TABLE order_status_history(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,order_id BIGINT UNSIGNED NOT NULL,status ENUM('pending','confirmed','shipping','delivered','completed','cancelled') NOT NULL,note VARCHAR(500),changed_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(changed_by) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_order_history(order_id,created_at)) ENGINE=InnoDB;
